  Object.assign(panel.style,{position:'fixed',left:'12px',top:'60px',zIndex:'2147483647',width:'min(380px,calc(100vw - 24px))',padding:'16px',borderRadius:'10px',background:'#20232b',color:'#f2f4f8',boxShadow:'0 6px 30px #0008'});
  panel.append(node('h3','连接本机 XLDB'),node('p','首次使用或清除连接后：双击 XLDB 解压文件夹中的 START-XLDB.cmd，在它打开的酒馆页面启用本脚本即可。不需要复制密钥；重新导入脚本不应删除本机数据或模型设置。'));
